package com.learnagent.quiz;import java.time.Instant;import java.util.*;import org.springframework.data.jpa.repository.JpaRepository;public interface QuizRepository extends JpaRepository<Quiz,UUID>{List<Quiz> findByCourseId(UUID courseId);Optional<Quiz> findByTitleAndCourseId(String title,UUID courseId);long countByStatus(QuizStatus status);long countByCompletedAtGreaterThanEqualAndCompletedAtLessThan(Instant start,Instant end);}
